func (s *provisionerServer) readS3Configuration(ctx context.Context, buf *bytes.Buffer) error {
	return s.withFilerClient(ctx, func(c filer_pb.SeaweedFilerClient) error {
		resp, err := c.LookupDirectoryEntry(ctx, &filer_pb.LookupDirectoryEntryRequest{
			Directory: filer.IamConfigDirectory,
			Name:      filer.IamIdentityFile,
		})
		if err != nil && !isNotFoundError(err) {
			return err
		}
		if resp != nil && resp.Entry != nil && resp.Entry.Content != nil {
			buf.Write(resp.Entry.Content)
		}
		return nil
	})
}

func (s *provisionerServer) saveS3Configuration(ctx context.Context, data []byte) error {
	return s.withFilerClient(ctx, func(c filer_pb.SeaweedFilerClient) error {
		_, err := c.UpdateEntry(ctx, &filer_pb.UpdateEntryRequest{
			Directory: filer.IamConfigDirectory,
			Entry: &filer_pb.Entry{
				Name:        filer.IamIdentityFile,
				Content:     data,
				IsDirectory: false,
			},
		})
		if err == nil || !isNotFoundError(err) {
			return err
		}
		_, err = c.CreateEntry(ctx, &filer_pb.CreateEntryRequest{
			Directory: filer.IamConfigDirectory,
			Entry: &filer_pb.Entry{
				Name:        filer.IamIdentityFile,
				Content:     data,
				IsDirectory: false,
			},
		})
		return err
	})
}

func (s *provisionerServer) readS3Identity(ctx context.Context, name string) ([]byte, error) {
	var buf bytes.Buffer
	err := s.withFilerClient(ctx, func(c filer_pb.SeaweedFilerClient) error {
		resp, err := c.LookupDirectoryEntry(ctx, &filer_pb.LookupDirectoryEntryRequest{
			Directory: filer.IamConfigDirectory + "/identities",
			Name:      name,
		})
		if err != nil && !isNotFoundError(err) {
			return err
		}
		if resp != nil && resp.Entry != nil && resp.Entry.Content != nil {
			buf.Write(resp.Entry.Content)
		}
		return nil
	})
	return buf.Bytes(), err
}

func mergeCredentials(base, extra []*iam_pb.Credential) []*iam_pb.Credential {
	seen := make(map[string]bool, len(base))
	for _, c := range base {
		seen[c.AccessKey] = true
	}
	for _, c := range extra {
		if !seen[c.AccessKey] {
			base = append(base, c)
			seen[c.AccessKey] = true
		}
	}
	return base
}

func mergeActions(base, extra []string) []string {
	for _, a := range extra {
		if !contains(base, a) {
			base = append(base, a)
		}
	}
	return base
}

func (s *provisionerServer) saveS3Identity(ctx context.Context, name string, data []byte) error {
	return s.withFilerClient(ctx, func(c filer_pb.SeaweedFilerClient) error {
		dir := filer.IamConfigDirectory + "/identities"
		_, err := c.UpdateEntry(ctx, &filer_pb.UpdateEntryRequest{
			Directory: dir,
			Entry: &filer_pb.Entry{
				Name:        name,
				Content:     data,
				IsDirectory: false,
			},
		})
		if err == nil {
			return nil
		}
		if !isNotFoundError(err) {
			return err
		}
		create, err := c.CreateEntry(ctx, &filer_pb.CreateEntryRequest{
			Directory: dir,
			Entry: &filer_pb.Entry{
				Name:        name,
				Content:     data,
				IsDirectory: false,
			},
		})
		if err != nil {
			return err
		}
		if create != nil && create.Error != "" {
			return errors.New(create.Error)
		}
		return nil
	})
}

func (s *provisionerServer) revokeBucketAccess(ctx context.Context, user string) error {
	// Reconcile the legacy single-file config first: an identity.json that was
	// never migrated may still carry the user, and a gateway reload between
	// the two writes could migrate it back into the per-identity file. Keep
	// going on error so the per-identity file is still deleted.
	legacyErr := s.configureS3Access(ctx, user, "", "", nil, true)
	// Newer filers keep one file per identity under /etc/iam/identities/ and
	// migrate identity.json away on write, so the legacy read-modify-write
	// above cannot remove them — delete the per-identity file directly.
	err := s.withFilerClient(ctx, func(c filer_pb.SeaweedFilerClient) error {
		resp, err := c.DeleteEntry(ctx, &filer_pb.DeleteEntryRequest{
			Directory: filer.IamConfigDirectory + "/identities",
			Name:      user + ".json",
		})
		if err != nil {
			return err
		}
		if resp.Error != "" && !strings.Contains(resp.Error, filer_pb.ErrNotFound.Error()) {
			return errors.New(resp.Error)
		}
		return nil
	})
	if err != nil && isNotFoundError(err) {
		err = nil
	}
	return errors.Join(legacyErr, err)
}

func (s *provisionerServer) configureS3Access(ctx context.Context, user, ak, sk string, actions []string, del bool) error {
	s.mu.Lock()
	defer s.mu.Unlock()

	var buf bytes.Buffer
	if err := s.readS3Configuration(ctx, &buf); err != nil {
		return err
	}

	cfg := &iam_pb.S3ApiConfiguration{}
	if buf.Len() > 0 {
		if err := filer.ParseS3ConfigurationFromBytes(buf.Bytes(), cfg); err != nil {
			return err
		}
	}

	// update cfg …
	idx := -1
	for i, id := range cfg.Identities {
		if id.Name == user {
			idx = i
			break
		}
	}

	if del {
		if idx < 0 {
			// Nothing removed — do not recreate a legacy identity.json that
			// the filer already migrated away.
			return nil
		}
		cfg.Identities = append(cfg.Identities[:idx], cfg.Identities[idx+1:]...)
	} else {
		if idx == -1 {
			cfg.Identities = append(cfg.Identities, &iam_pb.Identity{Name: user})
			idx = len(cfg.Identities) - 1
		}
		id := cfg.Identities[idx]
		if ak != "" && sk != "" {
			id.Credentials = append(id.Credentials, &iam_pb.Credential{AccessKey: ak, SecretKey: sk})
		}
		for _, a := range actions {
			if !contains(id.Actions, a) {
				id.Actions = append(id.Actions, a)
			}
		}
	}

	buf.Reset()
	filer.ProtoToText(&buf, cfg)
	return s.saveS3Configuration(ctx, buf.Bytes())
}

